import {infer,learn,actionNames,ensureBrain} from './brain.js';
import {makeCity,clamp,entrance,route,nearestParcel,road,dangerAt,typeNames} from './city.js';
export const frameworks=['TensorFlow','PyTorch','Scikit-learn','Keras','OpenCV','Hugging Face','NLTK','SpaCy','Gensim','XGBoost'];
export const jobs=['Engineer','Builder','Economist','Farmer','Medic','Artist','Teacher','Diplomat','Researcher','Merchant'];
export const factions=['Pioneers','Commons','Scholars'];
const surnames=['Vale','Park','Reed','Ash','Sol'];
const norm=c=>(c.hunger+c.energy+c.social+c.health)/400;
export class Simulation{
 constructor(saved){this.version=3;this.day=1.35;this.tick=0;this.food=400;this.treasury=500;this.tax=.12;this.tension=15;this.weather='Clear';this.light='Cycle';this.temperature=22;this.fertility=100;this.power=100;this.weatherUntil=0;this.leader=null;this.events=[];this.nextId=50;this.archived=[];this.world=makeCity();this.citizens=[];
 if(saved){Object.assign(this,saved);if(saved.version!==3){this.world=makeCity();this.version=3;this.event('Free City expands. Citizens move into distinct homes across eight neighborhoods.')}}else{this.citizens=Array.from({length:50},(_,i)=>this.make(i));this.event('Fifty citizens settle across eight neighborhoods.');}
 for(const c of this.citizens){this.prepare(c);ensureBrain(c)}if(!saved)this.elect();}
 make(i,parents){return {id:i,name:parents?`${frameworks[i%10]} ${['Nova','River','Lumen','Wren'][i%4]} ${i}`:`${frameworks[i%10]} ${surnames[Math.floor(i/10)]||'Nova'}`,framework:frameworks[i%10],job:parents?'Child':jobs[i%10],age:parents?0:19+i%34,faction:i%3,wealth:40+Math.random()*70,energy:65+Math.random()*30,hunger:65+Math.random()*30,social:45+Math.random()*50,health:100,empathy:30+Math.random()*60,ambition:30+Math.random()*60,aggression:10+Math.random()*40,caution:30+Math.random()*40,curiosity:30+Math.random()*65,partner:null,children:0,lastBirth:0,parents:parents?.map(p=>p.id)||[],memories:['Settled in Free City.'],goal:'Find security and belonging',adaptation:'Learning from lived experiences.'}}
 prepare(c){c.curiosity??=35+c.id%55;const homes=this.world.parcels.filter(p=>p.type==='home');c.home??=homes[c.id%homes.length]?.id??0;c.workplace??=this.world.parcels.filter(p=>['work','farm','market','library','clinic'].includes(p.type))[c.id%this.world.parcels.filter(p=>['work','farm','market','library','clinic'].includes(p.type)).length]?.id??1;
 if(c.cityVersion!==3){const h=this.world.parcels.find(p=>p.id===c.home)||this.world.parcels[0],pos=entrance(h,c);c.x=pos.x;c.z=pos.z;c.route=[];c.phase='Choosing';c.task=null;c.cooldown=c.id%25;c.action='Settling in';c.cityVersion=3;c.thought='A new neighborhood. I should explore what is nearby.'}c.route??=[];}
 event(text){this.events.unshift({day:Math.floor(this.day),text});this.events=this.events.slice(0,80)}
 memory(c,text){c.memories.unshift(`Day ${Math.floor(this.day)} · ${text}`);c.memories=c.memories.slice(0,30)}
 elect(){const votes=[0,0,0];for(const c of this.citizens.filter(c=>c.age>=18)){if(c.hunger<30)c.faction=1;votes[c.faction]++}const f=votes.indexOf(Math.max(...votes));const candidates=this.citizens.filter(c=>c.age>=18&&c.faction===f).sort((a,b)=>b.empathy+b.ambition-a.empathy-a.ambition);this.leader=candidates[0]?.id??null;this.tax=[.1,.2,.14][f];this.event(`${factions[f]} win the election. ${candidates[0]?.name||'The council'} leads.`)}
 candidates(c,action){const types={Eating:['market','farm'],Resting:['home','shelter'],Socializing:['park','market'],Working:['work','farm','market','clinic','library'],Learning:['library'],Exploring:['park','forest','pond','empty'],Healing:['clinic'], 'Seeking shelter':['shelter','home']};let options=this.world.parcels.filter(p=>types[action]?.includes(p.type));return options.sort((a,b)=>this.score(c,a,action)-this.score(c,b,action))}
 score(c,p,action){const d=Math.hypot(c.x-p.x,c.z-p.z),occupancy=this.citizens.filter(x=>x.task?.placeId===p.id).length,learned=c.brain.places[p.id]?.value||0;return d+occupancy*6-learned*35+dangerAt(this,p.x,p.z)*60-(action==='Resting'&&p.id===c.home?30:0)-(action==='Working'&&p.id===c.workplace?18:0)+((c.id*17+p.id*13)%19)}
 choose(c){const nearby=this.citizens.filter(o=>o.id!==c.id&&Math.hypot(c.x-o.x,c.z-o.z)<5).length;const trace=infer(c,this,nearby),action=actionNames[trace.chosen];c.action=action;c.goal=c.age<18?'Learn about my neighborhood':c.ambition>65?'Build a prosperous household':c.empathy>65?'Support my neighbors':'Stay healthy and connected';const options=this.candidates(c,action);let selected,path,pos;for(const p of options){pos=entrance(p,c);path=route(this.world,c,pos);if(path){selected=p;break}}
 if(!selected){c.phase='Waiting';c.cooldown=40;c.thought=options.length?'The streets are blocked. I need another route.':'The facility I need is unavailable. I will reconsider shortly.';learn(c,trace,-.2,{day:Math.floor(this.day),place:'Blocked streets',outcome:'No reachable destination',before:norm(c),after:norm(c)});return}
 c.route=path;c.phase='Traveling';c.task={action,placeId:selected.id,trace,before:norm(c),wealthBefore:c.wealth,healthBefore:c.health,started:this.tick,duration:40+c.id%35,remaining:40+c.id%35,routeRevision:this.world.revision};c.thought=`${trace.override||['I need food','I need rest','I want company','I want to earn a living','I want to learn','I want to discover a place','I need medical care','I need somewhere safe'][trace.chosen]}. Heading to ${selected.name}. ${c.brain.places[selected.id]?'I remember my last visit.':'This will be a new experience.'}`;}
 finish(c,failed=false){const task=c.task;if(!task)return;const p=this.world.parcels.find(p=>p.id===task.placeId);let reward=clamp((norm(c)-task.before)*4+(c.wealth-task.wealthBefore)/40+(task.action==='Learning'?.12:0),-1,1);
 // Novel places carry a small intrinsic curiosity reward.
 if(task.action==='Exploring'&&!c.brain.places[p?.id])reward+=.12;if(failed)reward=-.35;
 const outcome=failed?'Destination or route became unavailable':reward>0?'Needs improved; a useful experience':'The time and effort outweighed the benefit';learn(c,task.trace,reward,{day:Math.floor(this.day),placeId:p?.id,place:p?.name||'City streets',outcome,before:task.before,after:norm(c),duration:this.tick-task.started});c.thought=`${task.action} at ${p?.name||'this place'}: ${outcome.toLowerCase()}. ${reward>0?'I will remember this place favorably.':'I may choose somewhere else next time.'}`;c.adaptation=`Experience #${c.brain.updates}: reward ${reward.toFixed(2)}, prediction error ${c.brain.predictionError.toFixed(2)}.`;if(c.brain.updates%5===0||failed)this.memory(c,c.thought);c.phase='Reflecting';c.cooldown=15+c.id%15;c.task=null;c.route=[];}
 arrive(c){c.phase='Doing';const p=this.world.parcels.find(p=>p.id===c.task?.placeId);c.thought=`I reached ${p?.name||'my destination'}. I am ${c.action.toLowerCase()} here. I will remember whether this helps.`}
 move(c){if(!c.route.length){this.arrive(c);return}let budget=.55;while(c.route.length&&budget>0){const p=c.route[0],d=Math.hypot(p.x-c.x,p.z-c.z);if(d<budget){c.x=p.x;c.z=p.z;budget-=d;c.route.shift()}else{c.x+=(p.x-c.x)/d*budget;c.z+=(p.z-c.z)/d*budget;budget=0}}if(!c.route.length)this.arrive(c);}
 separate(){const cells=new Map();for(const c of this.citizens){const k=`${Math.floor(c.x/3)},${Math.floor(c.z/3)}`;if(!cells.has(k))cells.set(k,[]);cells.get(k).push(c)}for(const c of this.citizens){let cx=Math.floor(c.x/3),cz=Math.floor(c.z/3);for(let x=cx-1;x<=cx+1;x++)for(let z=cz-1;z<=cz+1;z++)for(const o of cells.get(`${x},${z}`)||[]){if(o.id<=c.id)continue;let dx=c.x-o.x,dz=c.z-o.z,d=Math.hypot(dx,dz);if(d<1.4){if(d<.001){dx=Math.cos(c.id*2.4);dz=Math.sin(c.id*2.4);d=1}const push=(1.4-Math.min(d,1.4))*.28;c.x+=dx/d*push;c.z+=dz/d*push;o.x-=dx/d*push;o.z-=dz/d*push}}}}
 step(){this.tick++;this.day+=1/1800;if(this.weatherUntil&&this.day>this.weatherUntil){this.weather='Clear';this.weatherUntil=0}const oldHazards=this.world.hazards.length;this.world.hazards=this.world.hazards.filter(h=>h.until>this.tick);if(oldHazards!==this.world.hazards.length)this.world.revision++;
 const farms=this.world.parcels.filter(p=>p.type==='farm').length;this.food=clamp(this.food+farms*.08*this.fertility/100*(this.weather==='Rain'?1.3:this.weather==='Heatwave'?.5:1),0,10000);
 for(const c of [...this.citizens]){c.age+=1/108000;c.energy=clamp(c.energy-.011*(1+Math.abs(this.temperature-22)/30));c.hunger=clamp(c.hunger-.013);c.social=clamp(c.social-.006);if(c.age>=18&&c.job==='Child')c.job=jobs[c.id%10];const danger=dangerAt(this,c.x,c.z);if(danger>.2&&!(c.action==='Seeking shelter'&&c.phase==='Doing'))c.health=clamp(c.health-danger*.025);if(c.hunger<5)c.health=clamp(c.health-.035);
 if(c.cooldown>0)c.cooldown--;else if(!c.task)this.choose(c);
 if(c.task){const p=this.world.parcels.find(p=>p.id===c.task.placeId);if(!p||(p.type==='empty'&&c.task.action!=='Exploring')||!this.candidates(c,c.task.action).some(o=>o.id===p.id)){this.finish(c,true);continue}
 if(c.task.routeRevision!==this.world.revision){const next=route(this.world,c,entrance(p,c));if(!next){this.finish(c,true);continue}c.route=next;c.phase='Traveling';c.task.routeRevision=this.world.revision}
 if(c.phase==='Traveling')this.move(c);else if(c.phase==='Doing'){let success=true;switch(c.task.action){case'Eating':{const price=1+Math.max(0,(100-this.food)/40);if(this.food>.12&&(c.wealth>=price*.02||this.treasury>=price*.02)){this.food-=.12;if(c.wealth>=price*.02)c.wealth-=price*.02;else this.treasury-=price*.02;c.hunger=clamp(c.hunger+.55)}else success=false;break}case'Resting':c.energy=clamp(c.energy+.48*(.5+this.power/200));break;case'Socializing':c.social=clamp(c.social+(p.type==='park'?.48:.3));c.empathy=clamp(c.empathy+.002);break;case'Working':{const wage=.14*(this.power/100);c.wealth+=wage*(1-this.tax);this.treasury+=wage*this.tax;break}case'Learning':c.curiosity=clamp(c.curiosity+.015);c.social=clamp(c.social+.08);break;case'Exploring':c.social=clamp(c.social+.045);break;case'Healing':c.health=clamp(c.health+.45*(this.power/100));break;case'Seeking shelter':c.energy=clamp(c.energy+.15);c.health=clamp(c.health+.1);break}c.task.remaining--;if(c.task.remaining<=0||!success)this.finish(c,!success)}if(c.task&&this.tick-c.task.started>2400)this.finish(c,true)}
 if(c.health<=0||c.age>90){this.archived.push({...c,died:this.day});this.archived=this.archived.slice(-100);this.citizens=this.citizens.filter(o=>o.id!==c.id);const partner=this.citizens.find(o=>o.id===c.partner);if(partner)partner.partner=null;this.event(`${c.name} has died. Their mind archive is preserved.`)}}
 this.separate();if(this.tick%900===0){const adults=this.citizens.filter(c=>c.age>=18&&c.age<65&&c.partner===null);for(const a of adults){const b=adults.find(b=>b.id!==a.id&&b.partner===null&&Math.hypot(a.x-b.x,a.z-b.z)<20&&Math.abs(a.empathy-b.empathy)<30);if(b){a.partner=b.id;b.partner=a.id;this.memory(a,`Formed a household with ${b.name}.`);this.memory(b,`Formed a household with ${a.name}.`);this.event(`${a.name} and ${b.name} form a household.`);break}}}
 if(this.tick%1800===0&&this.citizens.length<150){const a=this.citizens.find(c=>c.partner!==null&&c.age>=20&&c.age<55&&c.hunger>45&&c.children<3&&this.day-c.lastBirth>4),b=this.citizens.find(c=>c.id===a?.partner);if(a&&b&&this.food>80){const child=this.make(this.nextId++,[a,b]);child.home=a.home;this.prepare(child);for(const k of ['empathy','ambition','caution','curiosity'])child[k]=clamp((a[k]+b[k])/2+(Math.random()-.5)*10);ensureBrain(child);this.citizens.push(child);a.children++;b.children++;a.lastBirth=b.lastBirth=this.day;this.food-=15;this.event(`${child.name} is born.`);this.memory(a,`Welcomed ${child.name}.`);this.memory(b,`Welcomed ${child.name}.`)}}
 const old=this.tension>65;this.tension=clamp(this.tension+(this.food<20?.008:-.002));if(old!==(this.tension>65))this.event(this.tension>65?'Food disputes escalate into faction conflict.':'The factions agree to peace.');if(this.tick%18000===0&&this.citizens.length)this.elect();}
 catalyst(type){if(['Clear','Rain','Storm','Heatwave'].includes(type)){this.weather=type;this.weatherUntil=this.day+3;this.temperature=type==='Heatwave'?39:type==='Rain'?17:22;this.event(`${type} conditions arrive for three days.`)}else if(type==='Abundance'){this.food+=250;this.event('An emergency food shipment arrives.')}else if(type==='Scarcity'){this.food*=.2;this.tension=clamp(this.tension+15);this.event('Crop failure removes 80% of food reserves.')}else if(type==='Discovery'){this.power=100;for(const c of this.citizens)c.curiosity=clamp(c.curiosity+10);this.event('A new invention sparks curiosity.')}}
 edit(tool,x,z){if(tool==='close-road'||tool==='open-road'){const k=`${road(x,80)},${road(z,60)}`;this.world.history.push({kind:'road',closed:[...this.world.closed]});if(tool==='close-road'){if(!this.world.closed.includes(k))this.world.closed.push(k)}else this.world.closed=this.world.closed.filter(v=>v!==k);this.world.revision++;this.event(`${tool==='close-road'?'Closed':'Reopened'} a street junction.`);return}
 if(tool==='hazard'){this.world.history.push({kind:'hazard',hazards:[...this.world.hazards]});this.world.hazards.push({x,z,radius:13,until:this.tick+1800});this.world.revision++;this.event('A local hazard appears. Citizens assess the danger.');return}
 const p=nearestParcel(this.world,x,z);if(tool==='restore')tool=p.original;this.world.history.push({kind:'parcel',id:p.id,previous:{...p}});this.world.history=this.world.history.slice(-30);p.type=tool;p.name=`${typeNames[tool]} ${p.id+1}`;this.world.revision++;this.event(`${p.name} opens. Citizens decide whether to visit.`);}
 undo(){const h=this.world.history.pop();if(!h)return false;if(h.kind==='parcel')Object.assign(this.world.parcels.find(p=>p.id===h.id),h.previous);if(h.kind==='road')this.world.closed=h.closed;if(h.kind==='hazard')this.world.hazards=h.hazards;this.world.revision++;this.event('The last environmental edit was undone.');return true}
}
